import {mountFigure} from './figure-effects.js';
import {integrationMethods,integrationSources} from './integration-data.js';
import {correlation,pairedRows,timeValues,regulationRows,immuneCells,immuneScore,composition,validationRows,overlapCount,batchEffects} from './integration-lab.js';
const table=(headers,rows)=>`<div class="integration-table"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const ref=id=>`<a href="${integrationSources[id].url}" target="_blank" rel="noopener noreferrer">${integrationSources[id].label} ↗</a>`;
const metric=(value,label)=>`<div class="integration-metric"><strong>${value}</strong><span>${label}</span></div>`;
const slider=(label,key,value,min,max,step=1)=>`<label class="integration-slider">${label} <output>${value}</output><input type="range" aria-label="${label}" data-control="${key}" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;
const toggle=(key,value,labels)=>`<div class="integration-switch" role="group" aria-label="实验条件">${labels.map((label,i)=>`<button data-choice="${key}" data-value="${i}" aria-pressed="${value===i}">${label}</button>`).join('')}</div>`;
const svg=(body,label)=>`<svg class="integration-chart" viewBox="0 0 520 260" role="img" aria-label="${label}">${body}</svg>`;
const axes=(x,y)=>`<path d="M55 25V215H490" fill="none" stroke="#a9b6b4"/><text x="270" y="251" text-anchor="middle">${x}</text><text x="14" y="120" transform="rotate(-90 14 120)" text-anchor="middle">${y}</text>`;
function scatter(rows,xLabel,yLabel,max=10){return svg(axes(xLabel,yLabel)+[0,max/2,max].map(v=>`<text x="${55+v/max*420}" y="233" text-anchor="middle">${v}</text><text x="42" y="${219-v/max*180}" text-anchor="end">${v}</text>`).join('')+rows.map(r=>`<circle cx="${55+r.x/max*420}" cy="${215-r.y/max*180}" r="8" fill="${r.group?'#9c83c2':'#59a596'}"><title>${r.id}: ${r.x}, ${r.y}</title></circle><text x="${65+r.x/max*420}" y="${210-r.y/max*180}">${r.id}</text>`).join(''),`${xLabel}与${yLabel}散点图`);}
export function integrationReader(l){return `<div class="reader-heading"><span class="eyebrow">CASEBOOK / 研究问题到证据</span><h2>${l.name}</h2><p class="lesson-goal">${l.question}</p></div><div class="lesson-analogy"><span>先认识这份数据</span>${l.inputs.map(x=>`<p>${x}</p>`).join('')}<p>所有实验台数值均为教学模拟，用于练习分析逻辑；研究背景请阅读原文。</p></div><div class="lesson-sections">${l.steps.map((s,i)=>`<section><span class="lesson-number">0${i+1}</span><div><h3>${s.title}</h3><p>${s.action}</p><p><strong>你会得到：</strong>${s.readout}</p><p><strong>怎样理解：</strong>${s.meaning}</p></div></section>`).join('')}</div><div class="lesson-terms">${l.terms.map(([cn,en])=>`<span><strong>${cn}</strong><small>${en}</small></span>`).join('')}</div><div class="integration-source">研究 / 方法来源：${ref(l.source)}${l.lab==='immune'?` · ${ref('integrate-wnn')}`:''}</div><div class="reader-actions"><button class="outline" data-mode="process">打开动手分析 ↑</button><button class="primary" data-practice>做本课 4 道练习 →</button></div>`;}
export class IntegrationStudio{
 constructor(root,lesson,mode){this.root=root;this.lesson=lesson;this.mode=mode;this.step=0;this.timer=null;this.controller=new AbortController();this.values={aligned:0,balanced:0,batch:6,time:6,lag:8,within:0,weight:.5,b:80,grouped:0};this.selected='C2';this.method='mofa';this.root.addEventListener('click',e=>this.click(e),{signal:this.controller.signal});this.root.addEventListener('input',e=>{const el=e.target;if(!el.dataset.control)return;this.values[el.dataset.control]=Number(el.value);el.previousElementSibling.value=el.value;this.drawLab();},{signal:this.controller.signal});this.render();}
 destroy(){clearInterval(this.timer);this.timer=null;this.controller.abort();}
 getState(){return {topic:this.lesson.id,mode:this.mode,step:this.step,playing:!!this.timer,values:{...this.values},selected:this.selected,method:this.method};}
 click(e){const b=e.target.closest('button');if(!b)return;if(b.dataset.step!==undefined){this.step=+b.dataset.step;this.pause();this.render();}if(b.dataset.move){this.step=Math.max(0,Math.min(4,this.step+Number(b.dataset.move)));this.pause();this.render();}if(b.dataset.play!==undefined){if(this.timer)this.pause();else{if(this.step===4)this.step=0;this.timer=setInterval(()=>{this.step++;if(this.step>=4){this.step=4;this.pause();}this.render();},6000);}this.render();}if(b.dataset.choice){this.values[b.dataset.choice]=+b.dataset.value;this.render();}if(b.dataset.cell){this.selected=b.dataset.cell;this.drawLab();}if(b.dataset.method){this.method=b.dataset.method;this.render();}if(b.dataset.reset!==undefined){this.values={aligned:0,balanced:0,batch:6,time:6,lag:8,within:0,weight:.5,b:80,grouped:0};this.selected='C2';this.render();}}
 pause(){clearInterval(this.timer);this.timer=null;}
 render(){const l=this.lesson;this.root.innerHTML=`<div class="integration-studio"><header><span class="eyebrow">${l.tag} / MULTI-OMICS LAB</span><h2>${l.question}</h2><span class="integration-badge">教学模拟 · 数值非论文数据</span></header>${this.mode==='connections'?this.methods():this.mode==='process'?`<div class="integration-controls">${this.controls()}<button class="outline" data-reset>重置实验</button></div><div data-lab-output aria-live="polite"></div>`:this.walkthrough()}</div>`;if(this.mode==='process')this.drawLab();}
 walkthrough(){const s=this.lesson.steps[this.step];return `<div class="integration-steps" role="group" aria-label="案例推演步骤">${this.lesson.steps.map((s,i)=>`<button data-step="${i}" aria-pressed="${i===this.step}"><b>0${i+1}</b>${s.title}</button>`).join('')}</div><div class="evidence-flow" aria-label="多组学证据链">${['研究问题','配对数据','联合分析','验证假设'].map((x,i)=>`<span class="${Math.min(3,this.step)===i?'current':''}"><i>${['?','≋','⋈','✓'][i]}</i>${x}</span>`).join('')}</div><article class="integration-step-detail"><span class="eyebrow">STEP 0${this.step+1} / 05</span><h3>${s.title}</h3><p>${s.action}</p><div><strong>得到什么</strong><p>${s.readout}</p></div><p class="integration-insight">${s.meaning}</p></article><div class="integration-playbar"><button class="outline" data-move="-1" ${this.step===0?'disabled':''}>← 上一步</button><button class="outline" data-play>${this.timer?'暂停推演':'自动推演 · 每步 6 秒'}</button><button class="outline" data-move="1" ${this.step===4?'disabled':''}>下一步 →</button></div><button class="integration-lab-link" data-mode="process">现在动手：改变条件，观察结果 ↗</button>`;}
 controls(){const v=this.values;switch(this.lesson.lab){case'pairing':return toggle('aligned',v.aligned,['按行号连接（错误）','按样本 ID 对齐']);case'batch':return toggle('balanced',v.balanced,['完全混杂','平衡设计'])+slider('批次偏移（模拟单位）','batch',v.batch,0,10);case'time':return slider('采样时点（小时）','time',v.time,0,24)+slider('假设响应延迟（小时）','lag',v.lag,0,12);case'regulation':return toggle('within',v.within,['所有细胞','只看 A 类细胞']);case'immune':return slider('RNA 权重','weight',v.weight,0,1,.05);case'composition':return slider('菌 B 绝对数量（任意单位）','b',v.b,0,180,5);case'validation':return toggle('grouped',v.grouped,['按测量行拆分（泄漏）','按供者拆分']);}}
 drawLab(){const out=this.root.querySelector('[data-lab-output]');if(!out)return;const v=this.values;let html='';switch(this.lesson.lab){
 case'pairing':{const rows=pairedRows(!!v.aligned),r=correlation(rows.map(r=>r.x),rows.map(r=>r.y));html=metric(r.toFixed(2),'Pearson r · 描述线性相关，不是因果')+scatter(rows,'RNA（标准化单位）','蛋白质（标准化单位）',6)+table(['RNA 样本','RNA 值','蛋白样本','蛋白值','身份一致？'],rows.map(r=>[r.id,r.x,r.other,r.y,r.id===r.other?'✓':'错配']))+`<p class="integration-insight">${v.aligned?'ID 对齐后，配对才有生物学含义。这里特意构造了完全正相关的数据，真实研究通常存在噪声。':'现在按文件行号连接。即使能算出 r，错配也让它无法回答同一样本中两层是否共同变化。'}</p>`;break;}
 case'batch':{const e=batchEffects(!!v.balanced,v.batch);const rows=v.balanced?[['A','对照',10],['A','病例',12],['B','对照',10+v.batch],['B','病例',12+v.batch]]:[['A','对照',10],['B','病例',12+v.batch]];html=metric(e.observed.toFixed(1),'观察到的病例 − 对照均值差')+svg(rows.map((r,i)=>`<rect x="${70+i*105}" y="${215-r[2]*7}" width="60" height="${r[2]*7}" rx="8" fill="${r[1]==='病例'?'#ba7c9d':'#61a594'}"/><text x="${100+i*105}" y="${205-r[2]*7}" text-anchor="middle">${r[2]}</text><text x="${100+i*105}" y="238" text-anchor="middle">${r[0]}·${r[1]}</text>`).join(''),'各批次各组模拟均值')+table(['批次','分组','模拟均值'],rows)+`<p class="integration-insight">${v.balanced?'每个批次都有病例与对照，批次内差异均为 2。这个简化加性模型可以分离两种效应。':'模拟器预设疾病效应为 2，批次偏移为 '+v.batch+'，总差为 '+e.observed+'。研究者只看到总差，无法从完全混杂的数据唯一知道两者各贡献多少。'}</p><p class="integration-note">为说明设计而使用确定性均值，无误差项；真实分析还需要重复、效应不确定性及适合数据的模型。</p>`;break;}
 case'time':{const p=timeValues(v.time,v.lag),pts=Array.from({length:49},(_,i)=>i/2);const path=key=>pts.map((t,i)=>`${i?'L':'M'}${55+t/24*420},${215-timeValues(t,v.lag)[key]/4*180}`).join(' ');html=`<div class="integration-metrics">${metric(p.rna.toFixed(2)+'×','RNA / 基线')}${metric(p.protein.toFixed(2)+'×','蛋白质 / 基线')}</div>`+svg(axes('时间（小时，0—24）','相对基线倍数（0—4）')+`<path d="${path('rna')}" fill="none" stroke="#d1a457" stroke-width="4"/><path d="${path('protein')}" fill="none" stroke="#5c99b6" stroke-width="4"/><path d="M${55+v.time/24*420} 25V215" stroke="#596e69" stroke-dasharray="4 4"/><circle cx="${55+v.time/24*420}" cy="${215-p.rna/4*180}" r="6" fill="#d1a457" stroke="white" stroke-width="2"><title>RNA：${p.rna.toFixed(2)} 倍</title></circle><circle cx="${55+v.time/24*420}" cy="${215-p.protein/4*180}" r="6" fill="#5c99b6" stroke="white" stroke-width="2"><title>蛋白质：${p.protein.toFixed(2)} 倍</title></circle><text x="75" y="22">RNA（琥珀色） · 蛋白质（湖蓝）</text>`,'RNA 与蛋白质随时间变化的教学曲线')+`<p class="integration-insight">在 ${v.time} 小时采样，RNA 为 ${p.rna.toFixed(2)} 倍，蛋白质为 ${p.protein.toFixed(2)} 倍。把时点移到延迟之后，再观察蛋白质曲线。单时点的不一致可以推动你增加时间点。</p><details><summary>查看模拟公式</summary><p>RNA = 1 + 3 × (1 − exp(−t/3))；蛋白质 = 1 + 3 × (1 − exp(−max(0,t−延迟)/7))。这些是任意设定的响应曲线，不是从论文拟合的动力学参数。</p></details>`;break;}
 case'regulation':{const rows=regulationRows(!!v.within);html=metric(correlation(rows.map(r=>r.x),rows.map(r=>r.y)).toFixed(2),'Pearson r · '+(v.within?'A 类内部':'两类混合'))+scatter(rows,'ATAC（标准化单位）','RNA（标准化单位）')+table(['细胞','类型','ATAC','RNA'],rows.map(r=>[r.id,r.group?'B':'A',r.x,r.y]))+`<p class="integration-insight">${v.within?'A 类内部的 r = 0。这个例子中的总体相关来自两类细胞的均值差，不能据此宣布直接调控。':'青绿为 A 类，柔紫为 B 类。总体强正相关看起来很漂亮；切换到同一类型，检查关系还在不在。'}</p>`;break;}
 case'immune':{const c=immuneCells.find(c=>c.id===this.selected);html=`<div class="integration-cell-grid">${immuneCells.map(c=>`<button data-cell="${c.id}" aria-pressed="${this.selected===c.id}"><span style="--score:${immuneScore(c,v.weight)}"></span><strong>${c.id}</strong><small>${immuneScore(c,v.weight).toFixed(2)}</small></button>`).join('')}</div>`+metric(immuneScore(c,v.weight).toFixed(2),`${c.id} 联合标记分数 · 教学阈值 0.5`)+table(['细胞','RNA 分数','蛋白分数','联合分数','教学标记判定'],immuneCells.map(c=>[c.id,c.rna,c.protein,immuneScore(c,v.weight).toFixed(2),immuneScore(c,v.weight)>=.5?'较高':'较低']))+`<p class="integration-insight">${c.id}：${v.weight.toFixed(2)} × ${c.rna} + ${(1-v.weight).toFixed(2)} × ${c.protein} = ${immuneScore(c,v.weight).toFixed(2)}。调整权重，会改变冲突标记的联合判断。</p><p class="integration-note">线性加权教学示意，未运行 WNN。分数和 0.5 阈值无生物学标定，不能单独定义细胞身份。${ref('integrate-wnn')}</p>`;break;}
 case'composition':{const c=composition(v.b);html=`<div class="integration-metrics">${metric('20','菌 A 绝对数量 · 固定')}${metric(c.percent.toFixed(1)+'%','菌 A 相对丰度')}</div><div class="composition-bar" role="img" aria-label="菌 A 占 ${c.percent.toFixed(1)}%，菌 B 占其余部分"><span style="width:${c.percent}%"></span></div><p class="integration-note">青绿：菌 A；琥珀色：菌 B</p>`+table(['成员','绝对数量（任意单位）','相对丰度'],[['菌 A',20,c.percent.toFixed(1)+'%'],['菌 B',v.b,(100-c.percent).toFixed(1)+'%'],['总量',c.total,'100%']])+`<p class="integration-insight">A 的比例 = 20 ÷ (20 + ${v.b}) = ${c.percent.toFixed(1)}%。A 的绝对数量始终不变。减少 B，也能让 A 在相对丰度图上“上升”。</p><p class="integration-note">本实验只演示组成效应；代谢物来源需结合培养、定量或示踪实验。</p>`;break;}
 case'validation':{const rows=validationRows(!!v.grouped),n=overlapCount(rows);html=metric(n,'同时出现在训练和测试中的供者数')+table(['供者','时间点','分区'],rows.map(r=>[r.donor,r.time,`<span class="split-tag ${r.split==='测试'?'test':''}">${r.split}</span>`]))+`<p class="integration-insight">${n?'四位供者都泄漏到测试集。模型可能利用供者特征，分数不能代表预测新供者的能力。':'供者 A、B 用于训练，C、D 用于测试。测试供者未参与训练；预处理和筛特征也要保持这种隔离。'}</p><p class="integration-note">这里只演示划分规则，没有拟合预测模型。真实研究需要足够供者、适当分层和重复验证。</p>`;break;}}
 mountFigure(out,html);
 }
 methods(){const m=integrationMethods.find(m=>m.id===this.method);return `<p class="integration-note">先判断有没有同一样本、是否已有标签，再选择分析目标。</p><div class="integration-method-tabs">${integrationMethods.map(m=>`<button data-method="${m.id}" aria-pressed="${m.id===this.method}">${m.name}<small>${m.tag}</small></button>`).join('')}</div><article class="integration-step-detail"><span class="eyebrow">${m.tag}</span><h3>${m.name} · ${m.goal}</h3><p>${m.how}</p><p><strong>输入：</strong>${m.input}</p><p><strong>输出：</strong>${m.output}</p><p class="integration-insight">${m.caution}</p>${ref(m.source)}</article><details class="integration-comparison"><summary>展开五种策略的并排对比</summary>${table(['策略','适合回答','需要什么','得到什么'],integrationMethods.map(m=>[m.name,m.goal,m.input,m.output]))}</details><p class="integration-note">方法卡用于选择思路；本实验台没有运行 MOFA+、DIABLO 或 WNN。具体参数与限制请查看官方文档。</p>`;}
}
